<template><section><div class="title"><p>COMMERCE</p><h1>订单 / 支付</h1><span>Stripe 与 PayPal 订单</span></div><div class="payment-cards"><el-card><h3>Stripe</h3><p>PaymentIntent / Webhook</p><el-tag type="success">已接入</el-tag></el-card><el-card><h3>PayPal</h3><p>Orders v2 / Capture / Webhook</p><el-tag type="success">已接入</el-tag></el-card></div><el-card class="panel"><el-table :data="orders"><el-table-column prop="order_id" label="ID"/><el-table-column prop="order_no" label="订单号"/><el-table-column prop="user_id" label="用户"/><el-table-column prop="drama_id" label="短剧"/><el-table-column prop="provider" label="渠道"/><el-table-column prop="amount" label="金额"/><el-table-column prop="currency" label="币种"/><el-table-column prop="status" label="状态"/></el-table><el-empty v-if="!orders.length" description="暂无订单"/></el-card></section></template>